import client from './client';
import { filenameFrom, readBlobError } from './files';

export async function listCertificateRequests() {
  const { data } = await client.get('/api/certificados/solicitudes');
  return data;
}

// The unsigned PDF generated by the system, ready to be signed
export async function downloadCertificateToSign(requestId) {
  try {
    const response = await client.get(`/api/certificados/solicitudes/${requestId}/pdf`, { responseType: 'blob' });
    return {
      blob: response.data,
      filename: filenameFrom(response.headers, `certificate-${requestId}.pdf`),
    };
  } catch (err) {
    throw await readBlobError(err);
  }
}

export async function approveCertificate(requestId, signedPdf) {
  const body = new FormData();
  body.append('archivo', signedPdf);
  const { data } = await client.post(`/api/certificados/solicitudes/${requestId}/aprobar`, body, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
  return data;
}

export async function rejectCertificate(requestId, motivo) {
  const { data } = await client.patch(`/api/certificados/solicitudes/${requestId}/rechazar`, { motivo });
  return data;
}
